# Compute count of column '#' grouped by 'Directed by'
print(f"🔧 Computing count of '#' grouped by 'Directed by'")

# Check if columns exist and operation is valid
if '#' not in df.columns:
    print(f"❌ Error: Column '#' not found")
    print(f"Available columns: {df.columns.tolist()}")
elif 'Directed by' not in df.columns:
    print(f"❌ Error: Group by column 'Directed by' not found")
    print(f"Available columns: {df.columns.tolist()}")
elif "count" not in ['count', 'sum', 'avg', 'min', 'max']:
    print(f"❌ Error: Invalid operation 'count'. Valid operations: ['count', 'sum', 'avg', 'min', 'max']")
else:
    try:
        if "count" == "count":
            result = df.groupby('Directed by')['#'].count()
        elif "count" == "sum":
            result = df.groupby('Directed by')['#'].sum()
        elif "count" == "avg":
            result = df.groupby('Directed by')['#'].mean()
        elif "count" == "min":
            result = df.groupby('Directed by')['#'].min()
        elif "count" == "max":
            result = df.groupby('Directed by')['#'].max()

        print(f"✅ Count of '#' by 'Directed by':")
        print(result)

        # Convert to dataframe for consistency
        result_df = result.reset_index()
        result_df.columns = ['Directed by', f'count_result']
        print(f"\n🔍 Result as table:")
        print(result_df)

    except Exception as e:
        print(f"❌ Error computing grouped count: {e}")
        print(f"Column dtypes: {df[['#', 'Directed by']].dtypes}")
